/bin/bash -lc "node --input-type=module <<'EOF'
import { createApp } from './src/server.js';
import http from 'node:http';
const app=createApp(); const server=http.createServer(app); await new Promise(resolve=>server.listen(0,resolve));
const {port}=server.address();
async function req(path, opts={}) { const res=await fetch("'`http://127.0.0.1:${port}${path}`,opts); return {status:res.status, body:await res.text()}; }
for (const [label, result] of [
 ['"'GET /', await req('/')],
 ['unauthenticated list', await req('/api/appointments')],
 ['sign-in arbitrary id', await req('/api/sign-in',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({patientId:'other'})})],
 ['unknown detail', await req('/api/appointments/unknown')],
]) console.log(label, result);
